CREATE       PROCEDURE [synapse_fo].[usp_Insert_SubBillDeferralScheduleTable]
AS
/*
	Created by: Raj Maddala
	Created on: 2024-04-24 15:00:00
	Description: Insert stored procedure for SubBillDeferralScheduleTable from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[SubBillDeferralScheduleTable]
	(
		--[$FileName],
		--[_SysRowId],
		--[LSN],
		[LastProcessedChange_DateTime],
		[DataLakeModified_DateTime],
		[RECID],
		[SubBillDeferralConsolidatePriorPeriods],
		[SubBillDeferralAccount],
		[SubBillDeferralAmount],
		[SubBillDeferralEqualPerPeriod],
		[SubBillDeferralEventAllocationType],
		[SubBillDeferralEventPerUnit],
		[SubBillDeferralEventTemplateId],
		[SubBillDeferralExpirationAccount],
		[SubBillDeferralOnHoldAccount],
		[SubBillDeferralOnHoldTransferred],
		[SubBillDeferralRecognitionAccount],
		[SubBillDeferralRecognitionType],
		[SubBillDeferralScheduleCreationSource],
		[SubBillDeferralScheduleNumber],
		[SubBillDeferralScheduleStatus],
		[SubBillDeferralScheduleType],
		[SubBillDeferralSourceRecType],
		[SubBillDeferralTransactionType],
		[Description],
		[SourceRecId],
		[SourceTransLineDefRecId],
		[TransDate],
		[SubBillDeferralDistributionType],
		[SubBillScheduleDtlRecId],
		[SubBillDeferralShortTermAmount],
		[SubBillDeferralShortTermAccount],
		[SubBillDeferralOriginalScheduleAmount],
		[SubBillDeferralOriginalStartDate],
		[SubBillDeferralOriginalEndDate],
		[SubBillDeferralReclassificationDate],
		[SubBillDeferralInitialRecAcct],
		[SubBillDeferralRecOffAcct],
		[ExternalItemId],
		[CustomerLineNum],
		[CustInvoiceAccount],
		[InvoiceId],
		[ItemId],
		[SalesId],
		[DataAreaId],
		[PARTITION],
		[RECVERSION],
		[ProjTransId],
		[ProjFundingSource]
	)
	SELECT 
		--stg.[$FileName],
		--stg.[_SysRowId],
		--stg.--[LSN],
		stg.[LastProcessedChange_DateTime],
		stg.[DataLakeModified_DateTime],
		stg.[RECID],
		stg.[SubBillDeferralConsolidatePriorPeriods],
		stg.[SubBillDeferralAccount],
		stg.[SubBillDeferralAmount],
		stg.[SubBillDeferralEqualPerPeriod],
		stg.[SubBillDeferralEventAllocationType],
		stg.[SubBillDeferralEventPerUnit],
		stg.[SubBillDeferralEventTemplateId],
		stg.[SubBillDeferralExpirationAccount],
		stg.[SubBillDeferralOnHoldAccount],
		stg.[SubBillDeferralOnHoldTransferred],
		stg.[SubBillDeferralRecognitionAccount],
		stg.[SubBillDeferralRecognitionType],
		stg.[SubBillDeferralScheduleCreationSource],
		stg.[SubBillDeferralScheduleNumber],
		stg.[SubBillDeferralScheduleStatus],
		stg.[SubBillDeferralScheduleType],
		stg.[SubBillDeferralSourceRecType],
		stg.[SubBillDeferralTransactionType],
		stg.[Description],
		stg.[SourceRecId],
		stg.[SourceTransLineDefRecId],
		stg.[TransDate],
		stg.[SubBillDeferralDistributionType],
		stg.[SubBillScheduleDtlRecId],
		stg.[SubBillDeferralShortTermAmount],
		stg.[SubBillDeferralShortTermAccount],
		stg.[SubBillDeferralOriginalScheduleAmount],
		stg.[SubBillDeferralOriginalStartDate],
		stg.[SubBillDeferralOriginalEndDate],
		stg.[SubBillDeferralReclassificationDate],
		stg.[SubBillDeferralInitialRecAcct],
		stg.[SubBillDeferralRecOffAcct],
		stg.[ExternalItemId],
		stg.[CustomerLineNum],
		stg.[CustInvoiceAccount],
		stg.[InvoiceId],
		stg.[ItemId],
		stg.[SalesId],
		stg.[DataAreaId],
		stg.[PARTITION],
		stg.[RECVERSION],
		stg.[ProjTransId],
		stg.[ProjFundingSource]
	FROM [staging_fo].[SubBillDeferralScheduleTable] stg
		LEFT JOIN [synapse_fo].[SubBillDeferralScheduleTable] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL

END
